package android.media.session; import java.util.*; public class MediaSessionManager {public List<MediaController> getActiveSessions(android.content.ComponentName unused){String s=System.getProperty("scenario");if(s.equals("null-list"))return null;if(s.equals("empty"))return Arrays.asList(new MediaController("unselected"));if(s.equals("throw"))throw new IllegalStateException("PRIVATE SECRET never copy");if(s.equals("hang")){while(true){try{Thread.sleep(10000);}catch(Exception ignored){}}}List<MediaController> list=new ArrayList<>();if(s.equals("too-many-controllers")){for(int i=0;i<33;i++)list.add(new MediaController("unselected"));return list;}if(s.equals("too-many-sessions")||s.equals("total-oversize")||s.equals("session-limit")){int n=s.equals("too-many-sessions")?9:8;for(int i=0;i<n;i++)list.add(new MediaController("com.google.android.youtube.tv"));return list;}return Arrays.asList(new MediaController("unselected"),new MediaController("com.google.android.youtube.tv"),new MediaController("com.stremio.one"));}}
